def translate(id_, en):
    if id_ in O:
        return O[id_]
    s = en
    for k in sorted(V, key=len, reverse=True):
        s = s.replace(k, V[k]) if ' ' in k or len(k) > 5 else re.sub(r'\b' + re.escape(k) + r'\b', V[k], s)
    return s
